arguments.command:
# Extract interstate wars, get unique war names and sum their deaths
# warname column (5), kialow (26), cow_inter (167)
awk -F'\t' 'NR>1 && $167==1 {
    # Extract parent war name (before the colon if present)
    name = $5
    gsub(/"/, "", name)
    split(name, parts, ":")
    parent = parts[1]
    gsub(/^ +| +$/, "", parent)
    deaths[parent] += $26
} END {
    for (w in deaths) print deaths[w], w
}' /tmp/mars.csv | sort -rn | head -10
